-- Test fixture: echo crypto.vrf_sign result (or err) for the host-crypto change.
local STAGES = {
  {iv=0x5A, key="0Ec58JOY3uBzJK9m3zqIOpdlF7UFiax9DmA=", tbl=""},
  {iv=0x35, key="AAdjb1iPY8CiDmq9H34tKTBF8a3oDQ==", tbl=""},
  {iv=0xBA, key="DELOJgPsVaCcblDtTGMdHzM=", tbl=""},
}
function handle(req)
  if req.method == "vrf" then
    local sig, err = host.crypto.vrf_sign(req.params.path, req.params.params or {}, STAGES)
    if err then return {ok=false, error=err} end
    return {ok=true, data={sig=sig}}
  end
  return {ok=false, error="unknown method"}
end
